-- =============================================================================
-- AI Prompt Run User Attribution, Precision Widening, Indexes, and Fact View (6.2)
-- =============================================================================
-- Design: plans/ai-usage-analytics.md §6 and §7.1
--
-- This migration establishes the dimension keys and cost precision required for
-- trustworthy AI usage accounting:
--
--   1. AIPromptRun.UserID — the user on whose behalf a prompt ran. Written inline at run time.
--      It is the only source of user attribution for a DIRECT prompt run (no agent run), so it
--      carries information nothing else records.
--
--      There is deliberately NO AIPromptRun.AgentRunID. It was removed in
--      V202607241645__v5.50.x__Break_CodeGen_Cycle_Remove_PromptRun_AgentRunID.sql, and the
--      prompt-execution layer must not hold a key into the agent layer that sits on top of it.
--      Which agent run a prompt run belongs to is owned by the agent layer —
--      AIAgentRunStep.TargetLogID — and is resolved at query time by vwAIUsageFacts (5).
--
--   2. Precision widening:
--      * AIPromptRun.TotalCost      -> DECIMAL(19,8)
--      * AIPromptRun.DescendantCost -> DECIMAL(19,8)
--      * AIAgentRun.TotalCost       -> DECIMAL(19,8) (preserving default constraint)
--
--   3. IX_AIAgentRunStep_TargetLogID — makes (5)'s step lookup a seek. TargetLogID is
--      polymorphic (a prompt-run, agent-run or action-log ID), so it is not an FK and CodeGen
--      never indexed it.
--
--   4. Six nonclustered analytics indexes on AIPromptRun and AIAgentRun.
--
--   5. vwAIUsageFacts: normalized fact view, one row per prompt run. Not an entity's BaseView,
--      never dropped or regenerated by CodeGen
--      (packages/CodeGenLib/src/Database/providers/sqlserver/SQLServerCodeGenProvider.ts keys
--      off entity.BaseView). Refreshed by spRecompileAllViews on every mj migrate, references
--      base tables only, granted SELECT to cdp_UI, cdp_Developer, and cdp_Integration.
--
--   6. Permissions on the fact view.
--
--   7. Extended properties.
--
-- There is no data backfill. Historical agent-driven prompt runs get both their agent run and
-- their user from the step linkage inside vwAIUsageFacts (COALESCE(p.UserID, r.UserID)), and a
-- historical direct run has no recorded user to backfill from.
-- =============================================================================

-- 1. User attribution key on AIPromptRun (nullable: rows pre-date it; automated runs have no user)
ALTER TABLE [${flyway:defaultSchema}].[AIPromptRun]
    ADD [UserID] UNIQUEIDENTIFIER NULL;
GO

ALTER TABLE [${flyway:defaultSchema}].[AIPromptRun]
    ADD CONSTRAINT [FK_AIPromptRun_User] FOREIGN KEY ([UserID]) REFERENCES [${flyway:defaultSchema}].[User]([ID]);
GO

-- 2. Precision: every cost column on both run tables to decimal(19,8) (widening; no data loss)
ALTER TABLE [${flyway:defaultSchema}].[AIPromptRun] ALTER COLUMN [TotalCost]      DECIMAL(19,8) NULL;
ALTER TABLE [${flyway:defaultSchema}].[AIPromptRun] ALTER COLUMN [DescendantCost] DECIMAL(19,8) NULL;
GO

DECLARE @constraintName NVARCHAR(255);
SELECT @constraintName = d.name
FROM sys.tables t
JOIN sys.schemas s ON t.schema_id = s.schema_id
JOIN sys.columns c ON t.object_id = c.object_id
JOIN sys.default_constraints d ON c.default_object_id = d.object_id
WHERE s.name = '${flyway:defaultSchema}' AND t.name = 'AIAgentRun' AND c.name = 'TotalCost';

IF @constraintName IS NOT NULL
BEGIN
    SET @constraintName = QUOTENAME(@constraintName);
    EXEC('ALTER TABLE [${flyway:defaultSchema}].[AIAgentRun] DROP CONSTRAINT ' + @constraintName);
END
GO

ALTER TABLE [${flyway:defaultSchema}].[AIAgentRun] ALTER COLUMN [TotalCost] DECIMAL(19,8) NULL;
GO

ALTER TABLE [${flyway:defaultSchema}].[AIAgentRun] ADD CONSTRAINT [DF_AIAgentRun_TotalCost] DEFAULT ((0.00000000)) FOR [TotalCost];
GO

-- 3. Step-target lookup. Keyed (TargetLogID, StartedAt, ID) so the view's
--    `TOP 1 ... WHERE TargetLogID = @x ORDER BY StartedAt, ID` is a single seek with no sort.
--    Deliberately NOT filtered on StepType: the view's lookup carries no StepType predicate (the
--    equality on a near-unique GUID is what establishes the target is a prompt run), so a
--    StepType-filtered index would not be matched — and would drift as new step types begin
--    logging prompt runs, as Tool steps did.
CREATE NONCLUSTERED INDEX [IX_AIAgentRunStep_TargetLogID]
    ON [${flyway:defaultSchema}].[AIAgentRunStep] ([TargetLogID], [StartedAt], [ID])
    INCLUDE ([AgentRunID])
    WHERE [TargetLogID] IS NOT NULL;
GO

-- 4. Analytics indexes (explicitly required by MJ#4396 Part 4; these are NOT FK indexes — CodeGen makes those)
CREATE NONCLUSTERED INDEX [IX_AIPromptRun_RunAt]            ON [${flyway:defaultSchema}].[AIPromptRun] ([RunAt]) INCLUDE ([ModelID],[VendorID],[AgentID],[Cost],[TokensPrompt],[TokensCompletion]);
CREATE NONCLUSTERED INDEX [IX_AIPromptRun_ModelID_RunAt]    ON [${flyway:defaultSchema}].[AIPromptRun] ([ModelID],[RunAt]);
CREATE NONCLUSTERED INDEX [IX_AIPromptRun_VendorID_RunAt]   ON [${flyway:defaultSchema}].[AIPromptRun] ([VendorID],[RunAt]) WHERE [VendorID] IS NOT NULL;
CREATE NONCLUSTERED INDEX [IX_AIPromptRun_UserID_RunAt]     ON [${flyway:defaultSchema}].[AIPromptRun] ([UserID],[RunAt])   WHERE [UserID] IS NOT NULL;
CREATE NONCLUSTERED INDEX [IX_AIAgentRun_UserID_StartedAt]  ON [${flyway:defaultSchema}].[AIAgentRun]  ([UserID],[StartedAt]) WHERE [UserID] IS NOT NULL;
CREATE NONCLUSTERED INDEX [IX_AIAgentRun_CompanyID_StartedAt] ON [${flyway:defaultSchema}].[AIAgentRun] ([CompanyID],[StartedAt]) WHERE [CompanyID] IS NOT NULL;
GO

-- 5. Fact View (vwAIUsageFacts)
-- vwAIUsageFacts is not an entity's BaseView, is never dropped or regenerated by CodeGen
-- (packages/CodeGenLib/src/Database/providers/sqlserver/SQLServerCodeGenProvider.ts:98,:134 key off entity.BaseView),
-- and has no other home. It is refreshed by spRecompileAllViews on every mj migrate
-- (V202608251800__...spRecompileAllViews_Dependency_Order.sql:175), so it must stay valid;
-- it references base tables only, so a base-view regeneration cannot break it.
--
-- Agent-run resolution. A prompt run's agent run is the AgentRunID of the step whose TargetLogID
-- names it. Runs that are not a step's target inherit from their ParentID ancestry, which is at
-- most two levels deep from a step target:
--   * a parallel arm and a result selector hang off the parallel PARENT (the step's target);
--   * a JSON repair hangs off the run it repaired — which may itself be an arm.
-- So s0 (self), s1 (parent) and s2 (grandparent) cover every producer. Each lookup is TOP 1 over
-- (StartedAt, ID) so a run referenced by two steps resolves deterministically, and s1/s2 are
-- guarded on the nearer lookups missing so they cost nothing when s0 hits.
CREATE VIEW [${flyway:defaultSchema}].[vwAIUsageFacts]
AS
SELECT
    -- Keys
    p.[ID] AS [PromptRunID],
    ar.[AgentRunID],
    p.[ParentID] AS [ParentPromptRunID],

    -- Time. Buckets are taken from the full-precision UTC instant and TRUNCATED. A DATETIME2(0) cast
    -- rounds, which put a run at 22:59:59.7 into the 23:00 bucket and one at 23:59:59.7 into the next
    -- day; the DATETIME2(0) base literal also keeps DATEADD in DATETIME2 rather than DATETIME.
    p.[RunAt],
    CAST(SWITCHOFFSET(p.[RunAt], '+00:00') AS DATETIME2(7)) AS [RunAtUTC],
    DATEADD(hour,
            DATEDIFF(hour, CAST('2000-01-01' AS DATETIME2(0)), CAST(SWITCHOFFSET(p.[RunAt], '+00:00') AS DATETIME2(7))),
            CAST('2000-01-01' AS DATETIME2(0))) AS [HourBucket],
    CAST(CAST(SWITCHOFFSET(p.[RunAt], '+00:00') AS DATETIME2(7)) AS DATE) AS [DayBucket],

    -- Dimensions
    p.[PromptID],
    p.[ModelID],
    p.[VendorID],
    p.[AgentID],
    p.[ConfigurationID],
    COALESCE(p.[UserID], r.[UserID]) AS [UserID],
    r.[ConversationID],
    r.[PrimaryScopeEntityID],
    r.[PrimaryScopeRecordID],
    r.[CompanyID],
    p.[UsageTypeID],
    p.[RunType],
    p.[Status],
    p.[Success],

    -- SourceKind
    CASE
        WHEN p.[TestRunID] IS NOT NULL OR r.[TestRunID] IS NOT NULL THEN 'Test'
        WHEN r.[ScheduledJobRunID] IS NOT NULL THEN 'Scheduled'
        WHEN r.[ConversationID] IS NOT NULL THEN 'Conversation'
        WHEN ar.[AgentRunID] IS NOT NULL THEN 'Agent'
        ELSE 'Direct'
    END AS [SourceKind],

    -- Measures
    p.[TokensPrompt],
    p.[TokensCompletion],
    p.[TokensCacheRead],
    p.[TokensCacheWrite],
    p.[InputUnitsUsed],
    p.[OutputUnitsUsed],
    p.[Cost] AS [OwnCost],
    p.[CostCurrency],
    p.[ExecutionTimeMS],
    p.[QueueTime],
    p.[PromptTime],
    p.[CompletionTime],
    p.[FirstTokenTime],
    p.[FailoverAttempts],

    -- Flags
    CASE WHEN p.[Cost] IS NOT NULL THEN 1 ELSE 0 END AS [IsPriced],
    -- A parallel parent, and ONLY a parallel parent. An earlier revision also flagged any run
    -- with a child, which is wrong: ParentID is not parallel-only. AIPromptRunner's JSON-repair
    -- path sets it on an ordinary run (AIPromptRunner.ts, `parentPromptRunId: currentPromptRun.ID`)
    -- and AIModelRunner sets it from EmbeddingRunParams.ParentRunID. Under the old expression a
    -- $0.42 run that triggered a $0.01 repair was flagged as a parent and dropped from every
    -- `IsParallelParent = 0` cost sum — the total reported $0.01, while the run still counted as
    -- priced, so coverage read 100% with the money missing.
    CASE WHEN p.[RunType] = 'ParallelParent' THEN 1 ELSE 0 END AS [IsParallelParent],
    CASE WHEN p.[UsageTypeID] IS NOT NULL AND p.[InputUnitsUsed] IS NULL AND p.[OutputUnitsUsed] IS NULL THEN 1 ELSE 0 END AS [IsUnmeasured],
    CASE WHEN p.[CompletedAt] IS NOT NULL THEN 1 ELSE 0 END AS [IsCompleted]
FROM [${flyway:defaultSchema}].[AIPromptRun] p
LEFT JOIN [${flyway:defaultSchema}].[AIPromptRun] pp ON pp.[ID] = p.[ParentID]
OUTER APPLY (
    SELECT TOP 1 st.[AgentRunID]
    FROM [${flyway:defaultSchema}].[AIAgentRunStep] st
    WHERE st.[TargetLogID] = p.[ID]
    ORDER BY st.[StartedAt], st.[ID]
) s0
OUTER APPLY (
    SELECT TOP 1 st.[AgentRunID]
    FROM [${flyway:defaultSchema}].[AIAgentRunStep] st
    WHERE s0.[AgentRunID] IS NULL AND st.[TargetLogID] = p.[ParentID]
    ORDER BY st.[StartedAt], st.[ID]
) s1
OUTER APPLY (
    SELECT TOP 1 st.[AgentRunID]
    FROM [${flyway:defaultSchema}].[AIAgentRunStep] st
    WHERE s0.[AgentRunID] IS NULL AND s1.[AgentRunID] IS NULL AND st.[TargetLogID] = pp.[ParentID]
    ORDER BY st.[StartedAt], st.[ID]
) s2
CROSS APPLY (SELECT COALESCE(s0.[AgentRunID], s1.[AgentRunID], s2.[AgentRunID]) AS [AgentRunID]) ar
LEFT JOIN [${flyway:defaultSchema}].[AIAgentRun] r ON r.[ID] = ar.[AgentRunID];
GO

-- 6. Permissions
GRANT SELECT ON [${flyway:defaultSchema}].[vwAIUsageFacts] TO [cdp_UI], [cdp_Developer], [cdp_Integration];
GO

-- 7. Extended Properties
EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'The user on whose behalf this prompt was executed, written when the run is created. NULL for automated/unauthenticated runs and for runs that pre-date this column. For an agent-driven run the agent run''s user is also reachable through AIAgentRunStep.TargetLogID, which vwAIUsageFacts falls back to.',
    @level0type = N'SCHEMA', @level0name = N'${flyway:defaultSchema}',
    @level1type = N'TABLE',  @level1name = N'AIPromptRun',
    @level2type = N'COLUMN', @level2name = N'UserID';
GO

EXEC sp_addextendedproperty
    @name = N'MS_Description',
    @value = N'Normalized fact view: one row per AIPromptRun, with standardized time buckets, attribution dimensions, usage measures, and accounting flags. The agent run is resolved through AIAgentRunStep.TargetLogID (self, then ParentID ancestry), never stored on the prompt run. Not an entity base view.',
    @level0type = N'SCHEMA', @level0name = N'${flyway:defaultSchema}',
    @level1type = N'VIEW',   @level1name = N'vwAIUsageFacts';
GO























































